#include <iostream>
#include <string>
#include <vector>

// 1. Entity responsible ONLY for holding Order Data & Invariants
class Order {
public:
    std::string orderId;
    double amount;
    Order(std::string id, double amt) : orderId(std::move(id)), amount(amt) {}
};

// 2. Class responsible ONLY for Tax Calculation
class TaxCalculator {
public:
    static double calculateTotalWithTax(const Order& order, double taxRate) {
        return order.amount * (1.0 + taxRate);
    }
};

// 3. Class responsible ONLY for Database Persistence
class OrderRepository {
public:
    void saveToDatabase(const Order& order) {
        std::cout << "[DB] Saved order " << order.orderId << " to PostgreSQL.\n";
    }
};

// 4. Class responsible ONLY for Invoice Rendering
class InvoicePrinter {
public:
    void printHtmlReceipt(const Order& order, double total) {
        std::cout << "<div class='receipt'>Order #" << order.orderId 
                  << ": $" << total << "</div>\n";
    }
};

int main() {
    Order order{"ORD-101", 100.0};
    double total = TaxCalculator::calculateTotalWithTax(order, 0.08);

    OrderRepository repo;
    repo.saveToDatabase(order);

    InvoicePrinter printer;
    printer.printHtmlReceipt(order, total);
    return 0;
}

