#include <iostream>
#include <memory>
#include <vector>

// Abstract Discount Strategy Interface
class IDiscountStrategy {
public:
    virtual ~IDiscountStrategy() = default;
    virtual double applyDiscount(double rawPrice) const = 0;
};

// Concrete Discount 1: Flat 10%
class PercentageDiscount : public IDiscountStrategy {
    double percentage;
public:
    explicit PercentageDiscount(double pct) : percentage(pct) {}
    double applyDiscount(double rawPrice) const override {
        return rawPrice * (1.0 - percentage / 100.0);
    }
};

// Concrete Discount 2: Flat $20 off
class FlatVoucherDiscount : public IDiscountStrategy {
    double discountAmount;
public:
    explicit FlatVoucherDiscount(double amt) : discountAmount(amt) {}
    double applyDiscount(double rawPrice) const override {
        return std::max(0.0, rawPrice - discountAmount);
    }
};

// EXTENSION: Added Black Friday VIP discount with ZERO changes to existing classes!
class BlackFridayVipDiscount : public IDiscountStrategy {
public:
    double applyDiscount(double rawPrice) const override {
        return rawPrice * 0.50; // 50% off
    }
};

// Checkout Engine is CLOSED for modification, OPEN for extension!
class CheckoutEngine {
public:
    static double calculateFinal(double price, const IDiscountStrategy& strategy) {
        return strategy.applyDiscount(price);
    }
};

int main() {
    double basePrice = 200.0;
    BlackFridayVipDiscount vipDiscount;
    std::cout << "Final VIP Price: $" << CheckoutEngine::calculateFinal(basePrice, vipDiscount) << "\n";
    return 0;
}

