#include <iostream>
#include <cassert>

// Abstract Shape Contract: Focuses on what both truly share (Area)
class IShape {
public:
    virtual ~IShape() = default;
    virtual double getArea() const = 0;
};

// Rectangle maintains independent width and height
class Rectangle : public IShape {
private:
    double width, height;
public:
    Rectangle(double w, double h) : width(w), height(h) {}
    void setWidth(double w) { width = w; }
    void setHeight(double h) { height = h; }
    double getArea() const override { return width * height; }
};

// Square maintains equal side length independently (NOT derived from Rectangle!)
class Square : public IShape {
private:
    double side;
public:
    explicit Square(double s) : side(s) {}
    void setSide(double s) { side = s; }
    double getArea() const override { return side * side; }
};

void verifyAreaCalculation(const IShape& shape) {
    // 100% LSP Compliant: Any IShape subtype behaves predictably!
    std::cout << "Computed Area: " << shape.getArea() << "\n";
}

int main() {
    Rectangle rect{5.0, 10.0};
    Square sq{4.0};

    verifyAreaCalculation(rect); // Output: 50
    verifyAreaCalculation(sq);   // Output: 16
    return 0;
}

