#include <iostream>

// Role Interface 1
class IPrinter {
public:
    virtual ~IPrinter() = default;
    virtual void printDocument() = 0;
};

// Role Interface 2
class IScanner {
public:
    virtual ~IScanner() = default;
    virtual void scanDocument() = 0;
};

// Simple Printer implements ONLY IPrinter
class SimpleOfficePrinter : public IPrinter {
public:
    void printDocument() override {
        std::cout << "[SimplePrinter] Printing black & white document.\n";
    }
};

// High-end All-in-One Machine implements BOTH role interfaces!
class AllInOneSuperMachine : public IPrinter, public IScanner {
public:
    void printDocument() override {
        std::cout << "[SuperMachine] High-speed laser printing.\n";
    }
    void scanDocument() override {
        std::cout << "[SuperMachine] 1200 DPI optical scanning.\n";
    }
};

// Client needing ONLY printing functionality
void executePrintJob(IPrinter& printer) {
    printer.printDocument();
}

int main() {
    SimpleOfficePrinter simple;
    AllInOneSuperMachine fancy;

    executePrintJob(simple); // Works!
    executePrintJob(fancy);  // Works seamlessly!
    return 0;
}

