#include <iostream>
#include <memory>
#include <string>

// 1. Abstraction (Owned by High-Level Domain Policy)
class IPaymentProcessor {
public:
    virtual ~IPaymentProcessor() = default;
    virtual bool processTransaction(double amount) = 0;
};

// 2. High-Level Module: Depends ONLY upon IPaymentProcessor abstraction
class CheckoutService {
private:
    std::shared_ptr<IPaymentProcessor> paymentProcessor;

public:
    explicit CheckoutService(std::shared_ptr<IPaymentProcessor> processor)
        : paymentProcessor(std::move(processor)) {}

    void completePurchase(double total) {
        std::cout << "[CheckoutService] Processing purchase of $" << total << "...\n";
        if (paymentProcessor->processTransaction(total)) {
            std::cout << "[CheckoutService] Purchase successfully completed!\n";
        }
    }
};

// 3. Low-Level Detail: Implements abstraction
class StripeProcessor : public IPaymentProcessor {
public:
    bool processTransaction(double amount) override {
        std::cout << "  [Stripe API v3] Executed credit card charge for $" << amount << "\n";
        return true;
    }
};

int main() {
    auto stripe = std::make_shared<StripeProcessor>();
    CheckoutService checkout(stripe);
    checkout.completePurchase(199.95);
    return 0;
}

